"""The three special islands: Pinkan (pink Pokemon), Sunburst (Crystal Onix), Shamouti (the legend)."""
from orange_lib import town, wild, event, trainer

# Pinkan forms: smart IDs 9101+ (pink sprites generated by make_orange_art.py).
PINKAN = {9101: 12, 9102: 16, 9103: 17, 9104: 30, 9105: 33, 9106: 34, 9107: 46, 9108: 48,
          9109: 56, 9110: 57, 9111: 70, 9112: 102, 9113: 103, 9114: 111, 9115: 112, 9116: 123}
CRYSTAL_ONIX = 9201

# ---- Pinkan Island: a reserve guarded by Officer Jenny. Stop the poachers to earn a permit.
town("PINKAN_ISLAND", 54, [
    event("Officer Jenny", {
        "lines": ["Officer Jenny: Pinkan Island is a protected reserve.",
                  "The Pinkan Berries here turn the Pokemon pink! Poachers want them badly.",
                  "Team Rocket was spotted in the reserve. Please, stop them!"],
        "flag": "met_pinkan_jenny",
        "done": ["Officer Jenny: Team Rocket is somewhere in the reserve. Be careful!"]},
        flag_condition="not defeated_pinkan_rocket"),
    event("Get the Research Permit", {
        "requires": ["defeated_pinkan_rocket"],
        "lines": ["Officer Jenny: You chased off Team Rocket! The reserve is safe again.",
                  "Here's a research permit. You may catch Pinkan Pokemon to study them.",
                  "Treat them kindly. They only turn pink thanks to the berries here!"],
        "gift_item": {"PINKAN_PERMIT": 1}, "flag": "got_pinkan_permit"},
        condition="defeated_pinkan_rocket", flag_condition="not got_pinkan_permit"),
], local=[("Pinkan Reserve", "PINKAN_RESERVE", None)])
wild("PINKAN_RESERVE", "Pinkan Reserve", 54, "forest",
     {sid: w for sid, w in zip(PINKAN, [10, 10, 6, 6, 6, 3, 8, 8, 8, 4, 8, 8, 3, 8, 3, 4])},
     [("Pinkan Island", "PINKAN_ISLAND")],
     [trainer("Poacher Grunt", "ROCKET_GRUNT", "rocket_grunt_m.png", [24, 110]),
      trainer("Poacher Grunt", "ROCKET_GRUNT", "rocket_grunt_f.png", [42, 89])],
     extra=[event("STOP TEAM ROCKET", {
         "requires": ["met_pinkan_jenny"],
         "fail": ["Strange footprints lead into the berry trees..."],
         "lines": ["Jessie and James are stuffing Pinkan Berries into sacks!",
                   "Team Rocket: Pink Pokemon will make us rich! Out of our way!"],
         "battle": {"name": "Jessie & James", "class": "TEAM_ROCKET", "sprite": "rocket_team.png",
                    "team": [24, 110, 71, 52], "levels": [56, 56, 57, 58], "rewards": {"balls": 10},
                    "dialogue": {"player_won": ["Team Rocket: We're blasting off again!"]}},
         "flag": "defeated_pinkan_rocket"},
         condition="met_pinkan_jenny", flag_condition="not defeated_pinkan_rocket")],
     catch_cond=["has_balls", "has_item:PINKAN_PERMIT"])

# ---- Sunburst Island: Mateo the glassblower and the Crystal Onix.
town("SUNBURST_ISLAND", 57, [
    event("Mateo's Glass Workshop", {
        "lines": ["Mateo: Welcome to Sunburst Island, the island of glass!",
                  "A Crystal Onix lives in the cave by the lake. Its body is clear as glass.",
                  "Water and Electric attacks pass right through it. Only fire can crack it.",
                  "If you can calm it down, come back. I'll make you something special."],
        "flag": "met_mateo",
        "done": ["Mateo: The Crystal Onix is in the cave by the lake. Good luck!"]},
        flag_condition="not crystal_onix_defeated"),
    event("Show Mateo the Crystal Onix", {
        "requires": ["crystal_onix_defeated"],
        "lines": ["Mateo: You calmed the Crystal Onix! I've never seen glass shine like that.",
                  "I made this glass coin from sand by the lake. It's said to bring good fortune!"],
        "gift_item": {"AMULET_COIN": 1}, "flag": "got_mateo_gift"},
        condition="crystal_onix_defeated", flag_condition="not got_mateo_gift"),
], local=[("Crystal Cave", "CRYSTAL_CAVE", "met_mateo")])
wild("CRYSTAL_CAVE", "Crystal Cave", 58, "cave",
     {95: 18, 75: 15, 42: 15, 28: 10, 105: 8, 246: 5, 185: 8, 213: 7, 208: 3, 74: 11},
     [("Sunburst Island", "SUNBURST_ISLAND")],
     [trainer("Hiker Flint", "HIKER", "hiker.png", [95, 75, 208])],
     extra=[{"text": "CHALLENGE CRYSTAL ONIX", "action": "BOSS", "condition": "boss_not_defeated",
             "color": "GOLD"}],
     area_boss={"id": CRYSTAL_ONIX, "name": "Crystal Onix", "victory_flag": "crystal_onix_defeated"})

# ---- Shamouti Island: the legend of fire, ice and lightning, and the guardian of the sea.
TREASURES = ["has_item:FIRE_TREASURE", "has_item:ICE_TREASURE", "has_item:LIGHTNING_TREASURE"]
town("SHAMOUTI_ISLAND", 60, [
    event("The Shamouti Festival", {
        "lines": ["Melody: Welcome to the festival! Have you heard our island's legend?",
                  "Three titans of fire, ice and lightning must never fight.",
                  "If they do, only the guardian of the sea can stop them, and it needs help.",
                  "The legend says a Chosen One will gather a treasure from each titan's island.",
                  "You came by sea on festival day... I think you're the Chosen One!",
                  "Bring the three treasures to the Shrine, and the guardian will sing."],
        "flag": "heard_shamouti_legend",
        "done": ["Melody: Fire Island, Ice Island, Lightning Island. Then the Shrine!"]}),
], local=[("Fire Island", "FIRE_ISLAND", "heard_shamouti_legend"),
          ("Ice Island", "ICE_ISLAND", "heard_shamouti_legend"),
          ("Lightning Island", "LIGHTNING_ISLAND", "heard_shamouti_legend"),
          ("Shamouti Shrine", "SHAMOUTI_SHRINE", "heard_shamouti_legend")])


def titan_island(key, name, pool, bird, bird_name, treasure, btype):
    flag = f"shamouti_{bird_name.lower()}_calmed"
    wild(key, name, 62, btype, pool, [("Shamouti Island", "SHAMOUTI_ISLAND")],
         extra=[{"text": f"CALM {bird_name.upper()}", "action": "BOSS", "color": "GOLD",
                 "condition": "heard_shamouti_legend", "flag_condition": f"not {flag}",
                 "boss": {"id": bird, "name": bird_name, "level": 65, "no_catch": True, "victory_flag": flag,
                          "lines": [f"{bird_name} guards the island's shrine, crackling with power!"],
                          "won": [f"{bird_name} settles down and flies off.",
                                  f"In the shrine you find the {treasure.replace('_', ' ').title()}!"],
                          "rewards": {treasure: 1}}},
                event("SEARCH THE SHRINE", {
                    "lines": [f"You search {name}'s shrine again...",
                              f"There it is: the {treasure.replace('_', ' ').title()}, glowing on the altar!"],
                    "gift_item": {treasure: 1}},
                    condition=[flag, f"not:has_item:{treasure}", "not:shamouti_song_played"])])


titan_island("FIRE_ISLAND", "Fire Island", {58: 12, 77: 12, 78: 6, 126: 8, 218: 14, 219: 6, 228: 12, 229: 4, 37: 12, 38: 4, 240: 10},
             146, "Moltres", "FIRE_TREASURE", "mountain")
titan_island("ICE_ISLAND", "Ice Island", {86: 12, 87: 8, 124: 10, 215: 12, 220: 12, 221: 6, 225: 12, 131: 4, 238: 12, 91: 6, 90: 6},
             144, "Articuno", "ICE_TREASURE", "snow")
titan_island("LIGHTNING_ISLAND", "Lightning Island", {25: 10, 81: 12, 82: 6, 100: 12, 101: 6, 125: 6, 179: 14, 180: 8, 239: 10, 170: 8, 135: 2, 26: 6},
             145, "Zapdos", "LIGHTNING_TREASURE", "mountain")

wild("SHAMOUTI_SHRINE", "Shamouti Shrine", 64, "ocean",
     {79: 15, 80: 8, 199: 4, 72: 15, 73: 8, 120: 12, 222: 12, 226: 10, 171: 8, 230: 3, 117: 5},
     [("Shamouti Island", "SHAMOUTI_ISLAND")],
     extra=[event("PLACE THE TREASURES", {
                "requires": TREASURES,
                "fail": ["Three empty spots on the shrine's altar are shaped like treasures..."],
                "lines": ["You place the three treasures on the altar. They glow brightly!",
                          "Slowking: The titans are calm. Listen... the guardian of the sea is singing.",
                          "Something enormous is rising from the waves!"],
                "flag": "shamouti_song_played"},
                flag_condition="not shamouti_song_played"),
            {"text": "CHALLENGE LUGIA", "action": "BOSS", "color": "BLUE",
             "condition": ["shamouti_song_played", "boss_not_defeated"]}],
     area_boss={"id": 249, "name": "Lugia", "victory_flag": "shamouti_lugia_defeated"})
